input.script:
phase("起草");
await artifact.markdown("dwk-notes", "# E2E 笔记 v1\n\nE2E_DWK_NOTES_V1 初稿。\n", { title: "E2E 笔记", description: "E2E 两版笔记的说明", primary: true });
// 闸：第一版发布后停住，让用例先看到只有一版的产物条。
await world.run("node", ["-e", "const fs = require(\"node:fs\"); const timer = setInterval(() => { if (fs.existsSync(\"{{e2eRuntimeRoot}}/dwk-gate-a\")) clearInterval(timer); }, 100);"], { output: "discard", timeoutMs: 600000 });
phase("定稿");
// 同一个 id 再发布一次：第二版。标题与说明是每一版自己的，primary 跟着 id 走、不必重复。
await artifact.markdown("dwk-notes", "# E2E 笔记 v2\n\nE2E_DWK_NOTES_V2 定稿。\n", { title: "E2E 笔记", description: "E2E 两版笔记的说明" });
await artifact.file("dwk-scores", ".zcode-e2e/dwk-scores.csv", { title: "E2E 分数表" });
return "E2E_DWK_A_RESULT 笔记与分数表已交付。";

artifact.table("dwk-table", { title: "E2E 用例表", columns: [{ field: "name", label: "用例" }, { field: "ms", label: "耗时", unit: "ms" }], key: "name" });
artifact.metrics("dwk-metrics", { title: "E2E 指标", metrics: [{ field: "passed", label: "通过" }, { field: "failed", label: "失败" }, { field: "rate", label: "通过率", unit: "%" }] });
artifact.chart("dwk-chart", { title: "E2E 趋势", type: "line", x: { field: "round", label: "轮次" }, y: [{ field: "ms", label: "耗时", unit: "ms" }, { field: "mem", label: "内存", unit: "MB" }] });
artifact.board("dwk-board", { title: "E2E 看板", key: "name", status: "state", columns: ["待办", "进行中", "完成"], cardTitle: "name", detail: [{ field: "owner", label: "负责人" }] });
phase("汇报");
// 表：四个用例，alpha 报两次（按 key 覆盖同一行）。
report({ name: "alpha", ms: 120 }, "dwk-table");
report({ name: "beta", ms: 80 }, "dwk-table");
report({ name: "gamma", ms: 95 }, "dwk-table");
report({ name: "delta", ms: 60 }, "dwk-table");
report({ name: "alpha", ms: 110 }, "dwk-table");
// 指标：每块取最新一条带该字段的条目。
report({ passed: 7, failed: 1 }, "dwk-metrics");
report({ passed: 8, rate: 88.9 }, "dwk-metrics");
// 图：三个点，两条序列。
report({ round: 1, ms: 120, mem: 30 }, "dwk-chart");
report({ round: 2, ms: 100, mem: 31 }, "dwk-chart");
report({ round: 3, ms: 95, mem: 32 }, "dwk-chart");
// 看板：任务一后来移到「完成」，任务三的状态不在列里，落进「其他」。
report({ name: "任务一", state: "待办", owner: "甲" }, "dwk-board");
report({ name: "任务二", state: "进行中", owner: "乙" }, "dwk-board");
report({ name: "任务三", state: "搁置", owner: "丙" }, "dwk-board");
report({ name: "任务一", state: "完成", owner: "甲" }, "dwk-board");
await world.run("node", ["-e", "0"], { output: "discard" });
return "E2E_DWK_B_RESULT 看板已更新。";

artifact.metrics("dwk-empty", { title: "E2E 空指标", metrics: [{ field: "passed", label: "通过" }] });
artifact.table("dwk-partial", { title: "E2E 半张表", columns: [{ field: "name", label: "用例" }] });
phase("汇报");
report({ name: "epsilon" }, "dwk-partial");
report({ name: "zeta" }, "dwk-partial");
await world.run("node", ["-e", "0"], { output: "discard" });
// 列为空的看板：类型上合法，引擎的形状校验拒绝它，整个 run 出错。
artifact.board("E2E_DWK_BAD_BOARD", { title: "E2E 坏看板", key: "name", status: "state", columns: [] });
return "E2E_DWK_C_UNREACHABLE";
